def transform(grid):
    Ls=[grid[i*3:i*3+3] for i in range(4)]
    cols=[5,4,2,8]; prio=[0,1,3,2]  # layer colors; priority: 5>4>8>2
    h,w=len(Ls[0]),len(Ls[0][0])
    out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            for k in prio:
                if Ls[k][i][j]!=0: out[i][j]=cols[k]; break
    return out
